1: // Pure result mapping for extract-structure.mjs.
2: // Kept separate from the CLI entrypoint so unit tests do not import a shebang script.
3: const REQUIRED_STRUCTURE_ARRAY_FIELDS = [
4:   'functions',
5:   'classes',
6:   'imports',
7:   'exports',
8: ];
9: const OPTIONAL_STRUCTURE_ARRAY_FIELDS = [
10:   'sections',
11:   'definitions',
12:   'services',
13:   'endpoints',
14:   'steps',
15:   'resources',
16: ];
17: 
18: function isPlainObject(value) {
19:   if (value === null || typeof value !== 'object' || Array.isArray(value)) {
20:     return false;
21:   }
22: 
23:   const prototype = Object.getPrototypeOf(value);
24:   return prototype === Object.prototype || prototype === null;
25: }
26: 
27: function isStringArray(value) {
28:   return Array.isArray(value) && value.every(item => typeof item === 'string');
29: }
30: 
31: function isFiniteInteger(value) {
32:   return typeof value === 'number' &&
33:     Number.isFinite(value) &&
34:     Number.isInteger(value);
35: }
36: 
37: function isLineRange(value) {
38:   return Array.isArray(value) &&
39:     value.length === 2 &&
40:     value.every(isFiniteInteger);
41: }
42: 
43: function hasValidOptionalField(value, field, validator) {
44:   return value[field] === undefined || validator(value[field]);
45: }
46: 
47: function isValidEntryArray(value, validator) {
48:   return Array.isArray(value) &&
49:     value.every(entry => isPlainObject(entry) && validator(entry));
50: }
51: 
52: const STRUCTURE_ENTRY_VALIDATORS = {
53:   functions: entry =>
54:     typeof entry.name === 'string' &&
55:     isLineRange(entry.lineRange) &&
56:     isStringArray(entry.params) &&
57:     hasValidOptionalField(entry, 'returnType', value => typeof value === 'string'),
58:   classes: entry =>
59:     typeof entry.name === 'string' &&
60:     isLineRange(entry.lineRange) &&
61:     isStringArray(entry.methods) &&
62:     isStringArray(entry.properties),
63:   imports: entry =>
64:     typeof entry.source === 'string' &&
65:     isStringArray(entry.specifiers) &&
66:     isFiniteInteger(entry.lineNumber),
67:   exports: entry =>
68:     typeof entry.name === 'string' &&
69:     isFiniteInteger(entry.lineNumber) &&
70:     hasValidOptionalField(entry, 'isDefault', value => typeof value === 'boolean'),
71:   sections: entry =>
72:     typeof entry.name === 'string' &&
73:     isFiniteInteger(entry.level) &&
74:     isLineRange(entry.lineRange),
75:   definitions: entry =>
76:     typeof entry.name === 'string' &&
77:     typeof entry.kind === 'string' &&
78:     isLineRange(entry.lineRange) &&
79:     isStringArray(entry.fields),
80:   services: entry =>
81:     typeof entry.name === 'string' &&
82:     hasValidOptionalField(entry, 'image', value => typeof value === 'string') &&
83:     Array.isArray(entry.ports) &&
84:     entry.ports.every(isFiniteInteger) &&
85:     hasValidOptionalField(entry, 'lineRange', isLineRange),
86:   endpoints: entry =>
87:     hasValidOptionalField(entry, 'method', value => typeof value === 'string') &&
88:     typeof entry.path === 'string' &&
89:     isLineRange(entry.lineRange),
90:   steps: entry =>
91:     typeof entry.name === 'string' &&
92:     isLineRange(entry.lineRange),
93:   resources: entry =>
94:     typeof entry.name === 'string' &&
95:     typeof entry.kind === 'string' &&
96:     isLineRange(entry.lineRange),
97: };
98: 
99: function isValidStructuralAnalysis(analysis) {
100:   if (!isPlainObject(analysis)) {
101:     return false;
102:   }
103: 
104:   return REQUIRED_STRUCTURE_ARRAY_FIELDS.every(field =>
105:     isValidEntryArray(analysis[field], STRUCTURE_ENTRY_VALIDATORS[field])) &&
106:     OPTIONAL_STRUCTURE_ARRAY_FIELDS.every(field =>
107:       hasValidOptionalField(
108:         analysis,
109:         field,
110:         value => isValidEntryArray(value, STRUCTURE_ENTRY_VALIDATORS[field]),
111:       ));
112: }
113: 
114: function isValidCallGraph(callGraph) {
115:   return Array.isArray(callGraph) && callGraph.every(entry =>
116:     isPlainObject(entry) &&
117:     typeof entry.caller === 'string' &&
118:     typeof entry.callee === 'string' &&
119:     isFiniteInteger(entry.lineNumber));
120: }
121: 
122: function mapCallGraph(callGraph) {
123:   return callGraph && callGraph.length > 0
124:     ? callGraph.map(entry => ({
125:         caller: entry.caller,
126:         callee: entry.callee,
127:         lineNumber: entry.lineNumber,
128:       }))
129:     : null;
130: }
131: 
132: export function analyzeFileWithOutcomes(registry, file, content) {
133:   const wantsCallGraph =
134:     file.fileCategory === 'code' || file.fileCategory === 'script';
135:   const selectedPlugin = typeof registry.getPluginForFile === 'function'
136:     ? registry.getPluginForFile(file.path)
137:     : registry;
138: 
139:   if (selectedPlugin === null) {
140:     return {
141:       analysis: null,
142:       callGraph: null,
143:       structureOutcome: 'skipped',
144:       callGraphOutcome: 'skipped',
145:     };
146:   }
147: 
148:   const supportsFullAnalysis =
149:     typeof selectedPlugin?.analyzeFileFull === 'function';
150:   const supportsSeparateCallGraph =
151:     typeof selectedPlugin?.extractCallGraph === 'function';
152: 
153:   if (wantsCallGraph && supportsFullAnalysis) {
154:     let full;
155:     try {
156:       full = registry.analyzeFileFull(file.path, content);
157:     } catch {
158:       return {
159:         analysis: null,
160:         callGraph: null,
161:         structureOutcome: 'failed',
162:         callGraphOutcome: wantsCallGraph ? 'failed' : 'skipped',
163:       };
164:     }
165: 
166:     const analysis = isValidStructuralAnalysis(full?.structure)
167:       ? full.structure
168:       : null;
169:     const hasValidCallGraph = wantsCallGraph && isValidCallGraph(full?.callGraph);
170:     const callGraph = hasValidCallGraph ? mapCallGraph(full.callGraph) : null;
171: 
172:     return {
173:       analysis,
174:       callGraph,
175:       structureOutcome: analysis === null ? 'failed' : 'succeeded',
176:       callGraphOutcome: wantsCallGraph
177:         ? hasValidCallGraph ? 'succeeded' : 'failed'
178:         : 'skipped',
179:     };
180:   }
181: 
182:   let analysis = null;
